payload.css:
:host{display:block;position:absolute;inset:0;contain:layout paint}/* ForgeaX 2048 UI v3 */
.fx2048-shell{position:absolute;inset:0;overflow:hidden;container-type:size;display:grid;place-items:center;padding:clamp(10px,2.4cqh,28px);box-sizing:border-box;color:#f8f5ef;font-family:Inter,ui-rounded,"SF Pro Rounded",system-ui,sans-serif;background:radial-gradient(circle at 50% 15%,rgba(80,59,113,.42),transparent 38%),linear-gradient(145deg,rgba(9,13,25,.86),rgba(20,15,30,.78));isolation:isolate}
.fx2048-ambient{position:absolute;border-radius:999px;filter:blur(70px);opacity:.32;z-index:-1}.fx2048-ambient.one{width:38vw;height:38vw;background:#f59e5b;left:-14vw;bottom:-18vw}.fx2048-ambient.two{width:32vw;height:32vw;background:#7958d7;right:-10vw;top:-14vw}
.fx2048-card{width:min(94cqw,590px);height:min(96cqh,680px);min-height:0;display:flex;flex-direction:column;gap:clamp(7px,1.8cqh,16px);padding:clamp(13px,3cqh,30px);box-sizing:border-box;border:1px solid rgba(255,255,255,.14);border-radius:28px;background:linear-gradient(150deg,rgba(37,34,48,.94),rgba(24,22,33,.9));box-shadow:0 30px 90px rgba(0,0,0,.45),inset 0 1px rgba(255,255,255,.08);backdrop-filter:blur(20px)}
.fx2048-header{display:flex;align-items:flex-end;justify-content:space-between;gap:18px}.fx2048-kicker{font-size:10px;letter-spacing:.22em;font-weight:800;color:#e9b56e;white-space:nowrap}.fx2048-header h1{font-size:clamp(52px,10vh,78px);line-height:.88;letter-spacing:-.065em;margin:8px 0;color:#fff9ed;text-shadow:0 5px 25px rgba(237,194,46,.22)}.fx2048-header p{margin:10px 0 0;color:#aaa4b5;font-size:13px}
.fx2048-stats{display:flex;gap:8px}.fx2048-stats>div{position:relative;min-width:74px;padding:10px 12px;text-align:center;border-radius:13px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.07)}.fx2048-stats span{display:block;font-size:9px;letter-spacing:.13em;color:#a59eaf;font-weight:800}.fx2048-stats strong{display:block;margin-top:3px;font-size:20px;font-variant-numeric:tabular-nums}.fx2048-score em{position:absolute;right:10px;top:50%;color:#ffd28c;font:800 15px/1 inherit;font-style:normal;opacity:0;pointer-events:none;text-shadow:0 2px 8px rgba(0,0,0,.3)}
.fx2048-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;color:#aaa4b5;font-size:12px}.fx2048-toolbar>div{display:flex;gap:8px}button{font:inherit;white-space:nowrap}.fx2048-toolbar button,.fx2048-overlay button{border:0;border-radius:10px;padding:9px 12px;color:#f9f5ef;background:#6b556f;font-weight:750;cursor:pointer;transition:.16s transform,.16s opacity,.16s background}.fx2048-toolbar button:last-child,.fx2048-overlay button:last-child{background:#e8a862;color:#2d2130}.fx2048-toolbar button:hover,.fx2048-overlay button:hover{transform:translateY(-1px);filter:brightness(1.06)}.fx2048-toolbar button:focus-visible,.fx2048-overlay button:focus-visible{outline:2px solid #ffe0a3;outline-offset:3px}.fx2048-toolbar button:disabled{opacity:.35;cursor:default;transform:none}
.fx2048-board-wrap{min-height:0;flex:1;aspect-ratio:1;align-self:center;margin-inline:auto}.fx2048-board{position:relative;width:100%;height:100%;padding:clamp(7px,1.8cqh,13px);box-sizing:border-box;border-radius:22px;background:linear-gradient(145deg,#806e78,#665666);box-shadow:inset 0 2px 4px rgba(255,255,255,.12),0 18px 36px rgba(0,0,0,.3);touch-action:none;user-select:none;--gap:clamp(6px,1.5cqh,11px)}
.fx2048-cells{display:grid;grid-template-columns:repeat(4,1fr);gap:var(--gap);height:100%}.fx2048-cells>div{border-radius:14px;background:rgba(20,16,27,.26);box-shadow:inset 0 1px rgba(255,255,255,.06)}.fx2048-tiles{position:absolute;inset:clamp(8px,2.2vw,13px)}.fx2048-tile{position:absolute;width:calc((100% - 3 * var(--gap))/4);height:calc((100% - 3 * var(--gap))/4);left:calc(var(--col) * (25% + var(--gap)/4));top:calc(var(--row) * (25% + var(--gap)/4));display:grid;place-items:center;border-radius:14px;background:var(--tile-bg);color:var(--tile-fg);font-size:clamp(22px,calc(45px - var(--digits)*3px),45px);font-weight:850;letter-spacing:-.045em;box-shadow:0 5px 12px rgba(0,0,0,.18),inset 0 1px rgba(255,255,255,.35);transition:left 115ms ease,top 115ms ease;will-change:transform}.fx2048-tile[data-value="128"],.fx2048-tile[data-value="256"],.fx2048-tile[data-value="512"],.fx2048-tile[data-value="1024"],.fx2048-tile[data-value="2048"]{box-shadow:0 6px 18px color-mix(in srgb,var(--tile-bg) 62%,transparent),inset 0 1px rgba(255,255,255,.45)}.fx2048-tile[data-value="2048"]{outline:2px solid rgba(255,235,145,.5);outline-offset:-3px}.fx2048-tile.is-new{animation:fx2048-pop 180ms cubic-bezier(.2,1.5,.5,1)}
.fx2048-overlay{position:absolute;inset:0;z-index:5;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:24px;border-radius:22px;background:rgba(31,24,35,.84);backdrop-filter:blur(8px);animation:fx2048-fade 220ms ease}.fx2048-overlay[hidden]{display:none}.fx2048-overlay strong{font-size:clamp(34px,8vw,54px);letter-spacing:-.05em}.fx2048-overlay span{margin:10px 0 18px;color:#d3cbd7}.fx2048-overlay>div{display:flex;gap:9px}
.fx2048-card footer{display:flex;justify-content:center;gap:16px;flex-wrap:wrap;color:#8f8997;font-size:11px}.fx2048-card kbd{display:inline-grid;place-items:center;min-width:18px;height:18px;margin-right:2px;border-radius:5px;background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.1);font:700 10px inherit;color:#d8d2dc}
@keyframes fx2048-pop{0%{transform:scale(.2);opacity:0}80%{transform:scale(1.08)}100%{transform:scale(1)}}@keyframes fx2048-fade{from{opacity:0}to{opacity:1}}
@container(max-width:560px){.fx2048-card{border-radius:22px}.fx2048-header{align-items:center}.fx2048-header p{display:none}.fx2048-stats>div{min-width:58px;padding:8px}.fx2048-stats strong{font-size:17px}.fx2048-toolbar{align-items:flex-start}.fx2048-toolbar>span{max-width:120px}.fx2048-card footer{display:none}}
@container(max-height:600px){.fx2048-card{gap:7px;padding:12px 16px}.fx2048-header h1{font-size:42px;margin-block:5px}.fx2048-header p,.fx2048-card footer{display:none}.fx2048-stats>div{padding:7px 10px}.fx2048-toolbar button{padding:7px 10px}}
@media(prefers-reduced-motion:reduce){.fx2048-tile,.fx2048-overlay{animation:none!important;transition:none!important}}
